import React, { useState, useEffect, useRef, useMemo, useCallback } from 'react';
import { BusinessCardData, ProcessingTask } from './types';
import { extractCardInfo, detectBusinessCards } from './services/geminiService';
import CameraScanner from './components/CameraScanner';
import EditableField from './components/EditableField';
import PanZoomImage from './components/PanZoomImage';
import { getCardsMetadataFromDB, getCardById, saveCardToDB, deleteCardFromDB, clearAllCardsFromDB } from './services/dbService';
import { createExcelFile, parseExcelImport, ExportMode } from './services/excelService';
import { compressImage } from './utils/imageUtils';
import * as pdfjsLib from 'pdfjs-dist';

// Config PDF.js worker
const pdfjs = (pdfjsLib as any).default || pdfjsLib;
if (pdfjs.GlobalWorkerOptions) {
    pdfjs.GlobalWorkerOptions.workerSrc = `https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js`;
}

type ViewMode = 'camera' | 'file' | 'detail' | 'cropper';

interface CropRegion {
  id: string;
  x: number;
  y: number;
  w: number;
  h: number;
}

// --- Main App ---
const App: React.FC = () => {
  const [cards, setCards] = useState<BusinessCardData[]>([]);
  const [selectedCardId, setSelectedCardId] = useState<string | null>(null);

  // Form State for Editing
  const [formData, setFormData] = useState<BusinessCardData | null>(null);
  const [isFormDirty, setIsFormDirty] = useState(false);

  const [tasks, setTasks] = useState<ProcessingTask[]>([]);
  const [viewMode, setViewMode] = useState<ViewMode>('file');
  const [isProcessing, setIsProcessing] = useState(false);
  const [isMobile, setIsMobile] = useState(window.innerWidth < 768);
  const [activeCategory, setActiveCategory] = useState<'employer' | 'academic' | 'staff'>('employer');
  const [searchQuery, setSearchQuery] = useState('');
  const [isExporting, setIsExporting] = useState(false);
  const [isQueuePaused, setIsQueuePaused] = useState(false);
  const [isDragOver, setIsDragOver] = useState(false);
  const [showExportMenu, setShowExportMenu] = useState(false);

  // Refs
  const filesMap = useRef<Map<string, File | Blob>>(new Map());
  const tasksRef = useRef<ProcessingTask[]>([]);
  const processingMutex = useRef(false);
  const pausedRef = useRef(false);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const exportMenuRef = useRef<HTMLDivElement>(null);

  // Cropper States
  const [cropperImage, setCropperImage] = useState<string | null>(null);
  const [cropRegions, setCropRegions] = useState<CropRegion[]>([]);
  const [isDrawing, setIsDrawing] = useState(false);
  const [isMoving, setIsMoving] = useState(false);
  const [isResizing, setIsResizing] = useState<string | null>(null); 
  const [activeCropId, setActiveCropId] = useState<string | null>(null);
  const [startPos, setStartPos] = useState({ x: 0, y: 0 });
  const [initialRect, setInitialRect] = useState<CropRegion | null>(null);
  const [currentRect, setCurrentRect] = useState<CropRegion | null>(null);
  const cropperImgRef = useRef<HTMLImageElement>(null);
  const [pdfDoc, setPdfDoc] = useState<any>(null);
  const [currentPdfPage, setCurrentPdfPage] = useState(1);
  const [isRenderingPdf, setIsRenderingPdf] = useState(false);
  const [isAiDetecting, setIsAiDetecting] = useState(false);

  useEffect(() => { tasksRef.current = tasks; }, [tasks]);
  useEffect(() => { pausedRef.current = isQueuePaused; }, [isQueuePaused]);

  useEffect(() => {
    const handleResize = () => setIsMobile(window.innerWidth < 768);
    const handleClickOutside = (event: MouseEvent) => {
        if (exportMenuRef.current && !exportMenuRef.current.contains(event.target as Node)) {
            setShowExportMenu(false);
        }
    };
    window.addEventListener('resize', handleResize);
    document.addEventListener('mousedown', handleClickOutside);

    const loadInitialData = async () => {
      const savedCards = await getCardsMetadataFromDB();
      if (savedCards && savedCards.length > 0) {
        setCards(savedCards.sort((a, b) => b.scannedAt - a.scannedAt));
      }
    };
    loadInitialData();
    return () => {
        window.removeEventListener('resize', handleResize);
        document.removeEventListener('mousedown', handleClickOutside);
    };
  }, []);

  // Load selected card into form
  useEffect(() => {
    if (selectedCardId) {
      getCardById(selectedCardId).then(data => {
        if (data) {
             setFormData(data);
             setIsFormDirty(false);
        }
      });
    } else {
      setFormData(null);
      setIsFormDirty(false);
    }
  }, [selectedCardId]);

  // Save functionality
  const handleSave = async () => {
      if (!formData) return;
      await saveCardToDB(formData);
      // Update local list without re-fetching everything
      setCards(prev => prev.map(c => c.id === formData.id ? { ...c, ...formData } : c));
      setIsFormDirty(false);
      // Optional: Show a subtle toast
      const btn = document.getElementById('save-btn');
      if (btn) {
          const originalText = btn.innerHTML;
          btn.innerHTML = '<i class="fa-solid fa-check"></i> 已儲存';
          setTimeout(() => btn.innerHTML = originalText, 2000);
      }
  };

  const updateField = (field: keyof BusinessCardData, value: string) => {
      if (!formData) return;
      setFormData({ ...formData, [field]: value });
      setIsFormDirty(true);
  };

  // --- Async Queue Logic ---
  const performSingleTask = async (task: ProcessingTask) => {
    try {
        const fileObj = filesMap.current.get(task.id);
        if (!fileObj) throw new Error("File missing from memory");

        const processWithTimeout = async () => {
            const base64Data = await compressImage(fileObj);
            const info = await extractCardInfo(base64Data, 'image/jpeg');
            return { base64Data, info };
        };

        const timeoutPromise = new Promise<{base64Data: string, info: any}>((_, reject) => 
            setTimeout(() => reject(new Error("Timeout (45s)")), 45000)
        );

        const { base64Data, info } = await Promise.race([processWithTimeout(), timeoutPromise]);

        const newCard: BusinessCardData = {
            notes: '',
            prefix: '',
            ...info,
            id: task.id,
            scannedAt: Date.now(),
            source: 'QS Hub Scanner',
            imageUrl: `data:image/jpeg;base64,${base64Data}`,
        };

        await saveCardToDB(newCard);
        const { imageUrl, ...newCardMeta } = newCard;
        setCards(prev => [newCardMeta as BusinessCardData, ...prev].sort((a,b) => b.scannedAt - a.scannedAt));
        setTasks(prev => prev.map(t => t.id === task.id ? { ...t, status: 'completed' } : t));
        filesMap.current.delete(task.id);

    } catch (err: any) {
        console.error(`Task ${task.id} Failed:`, err);
        if (err.message === 'API_KEY_INVALID') window.aistudio?.openSelectKey();
        let errorMsg = err.message || "處理失敗";
        if (errorMsg.includes('500') || errorMsg.includes('Internal')) errorMsg = "伺服器錯誤 (500)";
        if (errorMsg.includes('Timeout')) errorMsg = "AI 回應超時";
        setTasks(prev => prev.map(t => t.id === task.id ? { ...t, status: 'error', error: errorMsg } : t));
    }
  };

  const processQueue = useCallback(async () => {
    if (processingMutex.current || pausedRef.current) return;
    processingMutex.current = true;
    setIsProcessing(true);
    try {
        while (true) {
            if (pausedRef.current) break;
            const nextTask = tasksRef.current.find(t => t.status === 'pending');
            if (!nextTask) break;
            setTasks(prev => prev.map(t => t.id === nextTask.id ? { ...t, status: 'processing' } : t));
            await performSingleTask(nextTask);
            await new Promise(r => setTimeout(r, 500));
        }
    } finally {
        processingMutex.current = false;
        setIsProcessing(false);
    }
  }, []);

  useEffect(() => {
    if (!isQueuePaused && !isProcessing) {
        processQueue();
    }
  }, [tasks, isQueuePaused, isProcessing, processQueue]);

  // --- Handlers ---
  const handleDeleteCard = async (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    if (!window.confirm("確定要刪除這筆名片資料嗎？")) return;
    await deleteCardFromDB(id);
    setCards(prev => prev.filter(c => c.id !== id));
    if (selectedCardId === id) {
      setSelectedCardId(null);
      setFormData(null);
      setViewMode('file');
    }
  };

  const handleClearAll = async () => {
    if (cards.length === 0) return;
    if (!window.confirm("⚠️ 警告：這將會永久刪除所有紀錄！")) return;
    const success = await clearAllCardsFromDB();
    if (success) {
      setCards([]);
      setSelectedCardId(null);
      setFormData(null);
      setViewMode('file');
    }
  };

  // --- Mobile Share Handler ---
  const handleShare = async () => {
      if (!formData) return;

      const shareText = [
          `稱謂: ${formData.prefix || ''}`,
          `姓名: ${formData.lastName} ${formData.firstName}`,
          `職稱: ${formData.title || ''}`,
          `公司/機構: ${formData.company || ''}`,
          `部門: ${formData.department || ''}`,
          formData.phone ? `電話: ${formData.phone}` : '',
          formData.email ? `信箱: ${formData.email}` : '',
          formData.website ? `網站: ${formData.website}` : '',
          formData.address ? `地址: ${formData.address}` : ''
      ].filter(line => !line.endsWith(': ')).join('\n');

      if (navigator.share) {
          try {
              await navigator.share({
                  title: `${formData.firstName} ${formData.lastName}`,
                  text: shareText
              });
          } catch (err) {
              console.warn('Share cancelled or failed', err);
          }
      } else {
          navigator.clipboard.writeText(shareText);
          alert("已複製到剪貼簿");
      }
  };

  const handleExport = async (mode: ExportMode) => {
    let targetCards: BusinessCardData[] = [];

    // Determine Target Cards
    if (mode === 'single') {
        if (!formData) return;
        targetCards = [formData];
    } else if (mode === 'employer') {
        targetCards = cards.filter(c => c.category === 'employer');
    } else if (mode === 'academic') {
        targetCards = cards.filter(c => c.category === 'academic');
    } else if (mode === 'staff') {
        targetCards = cards.filter(c => c.category === 'staff');
    } else {
        targetCards = cards;
    }

    if (targetCards.length === 0) { alert("無符合資料可匯出"); return; }

    // JSON Export Logic
    if (mode === 'json') {
        const jsonString = JSON.stringify(targetCards, null, 2);
        const blob = new Blob([jsonString], { type: "application/json" });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = `QS_Export_JSON_${new Date().toISOString().split('T')[0]}.json`;
        document.body.appendChild(a);
        a.click();
        document.body.removeChild(a);
        URL.revokeObjectURL(url);
        setShowExportMenu(false);
        return;
    }

    // Excel Export Logic
    setIsExporting(true);
    setShowExportMenu(false);
    try {
      const excelFile = await createExcelFile(targetCards, mode);
      const url = URL.createObjectURL(excelFile);
      const a = document.createElement('a');
      a.href = url; a.download = excelFile.name;
      document.body.appendChild(a); a.click(); document.body.removeChild(a); URL.revokeObjectURL(url);
    } catch (err: any) { alert("匯出失敗：" + err.message); } finally { setIsExporting(false); }
  };

  const processFiles = async (files: FileList | null) => {
    if (!files || files.length === 0) return;

    // Import Excel Logic
    if (files.length === 1 && files[0].name.endsWith('.xlsx')) {
        try {
            const json = await parseExcelImport(files[0]);
            let importedCount = 0;
            for (const row of json as any[]) {
                if (row.SYSTEM_ID && row.IMAGE_BASE64) {
                    const restoredCard: BusinessCardData = {
                        id: row.SYSTEM_ID,
                        scannedAt: row.scannedAt || Date.now(),
                        category: row.category || 'employer',
                        source: row.source || 'Import',
                        firstName: row.firstName || '', lastName: row.lastName || '', prefix: row.prefix || '',
                        title: row.title || '', company: row.company || '', department: row.department || '',
                        industry: row.industry || '', country: row.country || '', email: row.email || '',
                        phone: row.phone || '', subject: row.subject || '', website: row.website || '',
                        address: row.address || '', reasoning: row.reasoning || '',
                        notes: row.notes || '',
                        imageUrl: row.IMAGE_BASE64,
                        translations: {
                            title: row.trans_title, company: row.trans_company, department: row.trans_dept,
                            industry: row.trans_ind, subject: row.trans_subj, country: row.trans_ctry
                        }
                    };
                    await saveCardToDB(restoredCard);
                    importedCount++;
                }
            }
            alert(`成功還原 ${importedCount} 筆名片資料！`);
            const savedCards = await getCardsMetadataFromDB();
            setCards(savedCards.sort((a, b) => b.scannedAt - a.scannedAt));
            if (fileInputRef.current) fileInputRef.current.value = '';
            return;
        } catch (e) {
            console.error(e);
            alert("Excel 還原失敗：格式不正確或檔案損毀");
            return;
        }
    }

    const firstFile = files[0];

    // PDF / Single Image for Cropper
    if (firstFile.type === 'application/pdf') {
        const reader = new FileReader();
        reader.onload = async (ev) => {
            const typedarray = new Uint8Array(ev.target?.result as ArrayBuffer);
            try {
                const pdf = await pdfjs.getDocument(typedarray).promise;
                setPdfDoc(pdf); setCurrentPdfPage(1); await renderPdfPage(pdf, 1);
                setViewMode('cropper');
            } catch (err) { alert("PDF 解析失敗"); }
        };
        reader.readAsArrayBuffer(firstFile);
        if (fileInputRef.current) fileInputRef.current.value = '';
        return;
    }

    if (files.length === 1 && firstFile.type.startsWith('image/')) {
        const reader = new FileReader();
        reader.onload = (event) => {
            const b64 = event.target?.result as string;
            setCropperImage(b64); setCropRegions([]); setViewMode('cropper');
            autoDetectInCropper(b64.split(',')[1]);
        };
        reader.readAsDataURL(firstFile);
        if (fileInputRef.current) fileInputRef.current.value = '';
        return;
    }

    // Batch Processing
    const newTasks: ProcessingTask[] = [];
    for (const f of Array.from(files) as File[]) {
      if (!f.type.startsWith('image/')) continue;
      const id = crypto.randomUUID();
      filesMap.current.set(id, f);
      const previewUrl = URL.createObjectURL(f);
      newTasks.push({ id, fileName: f.name, status: 'pending', progress: 0, batchIndex: 1, previewUrl });
    }
    setTasks(prev => [...prev, ...newTasks]);
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  // Drag & Drop
  const onDragOver = (e: React.DragEvent) => { e.preventDefault(); setIsDragOver(true); };
  const onDragLeave = (e: React.DragEvent) => { e.preventDefault(); setIsDragOver(false); };
  const onDrop = (e: React.DragEvent) => {
      e.preventDefault(); setIsDragOver(false);
      processFiles(e.dataTransfer.files);
  };

  // --- Cropper Functions (Same logic, slightly condensed) ---
  const autoDetectInCropper = async (b64: string) => {
    setIsAiDetecting(true);
    try {
      const boxes = await detectBusinessCards(b64);
      setCropRegions(boxes.map(box => ({
        id: crypto.randomUUID(), x: (box.xmin/1000)*100, y: (box.ymin/1000)*100, w: ((box.xmax-box.xmin)/1000)*100, h: ((box.ymax-box.ymin)/1000)*100
      })));
    } catch (e) { console.warn(e); } finally { setIsAiDetecting(false); }
  };
  const renderPdfPage = async (pdf: any, pageNum: number) => {
    setIsRenderingPdf(true);
    try {
        const page = await pdf.getPage(pageNum);
        const viewport = page.getViewport({ scale: 2 });
        const canvas = document.createElement('canvas');
        canvas.height = viewport.height; canvas.width = viewport.width;
        const context = canvas.getContext('2d');
        if (context) {
            await page.render({ canvasContext: context, viewport }).promise;
            const b64 = canvas.toDataURL('image/jpeg');
            setCropperImage(b64); setCropRegions([]); autoDetectInCropper(b64.split(',')[1]);
        }
    } catch (e) { alert("無法讀取 PDF"); } finally { setIsRenderingPdf(false); }
  };
  // (Cropper Interaction Handlers omitted for brevity but present in logic)
  const getMousePos = (e: React.MouseEvent | React.TouchEvent) => {
      if (!cropperImgRef.current) return { x: 0, y: 0 };
      const rect = cropperImgRef.current.getBoundingClientRect();
      const clientX = 'touches' in e ? e.touches[0].clientX : (e as React.MouseEvent).clientX;
      const clientY = 'touches' in e ? e.touches[0].clientY : (e as React.MouseEvent).clientY;
      return { x: ((clientX - rect.left) / rect.width) * 100, y: ((clientY - rect.top) / rect.height) * 100 };
  };
  const handleCropStart = (e: React.MouseEvent | React.TouchEvent, action: 'draw' | 'move' | 'resize' = 'draw', cropId?: string, handle?: string) => {
      const pos = getMousePos(e); setStartPos(pos);
      if (action === 'draw') { setCurrentRect({ id: 'temp', x: pos.x, y: pos.y, w: 0, h: 0 }); setIsDrawing(true); setActiveCropId(null); }
      else if (action === 'move' && cropId) { const crop = cropRegions.find(r => r.id === cropId); if (crop) { setInitialRect({ ...crop }); setIsMoving(true); setActiveCropId(cropId); } }
      else if (action === 'resize' && cropId && handle) { const crop = cropRegions.find(r => r.id === cropId); if (crop) { setInitialRect({ ...crop }); setIsResizing(handle); setActiveCropId(cropId); } }
  };
  const handleCropMove = (e: React.MouseEvent | React.TouchEvent) => {
      const pos = getMousePos(e);
      if (isDrawing && currentRect) { setCurrentRect({ ...currentRect, x: Math.min(pos.x, startPos.x), y: Math.min(pos.y, startPos.y), w: Math.abs(pos.x - startPos.x), h: Math.abs(pos.y - startPos.y) }); }
      else if (isMoving && activeCropId && initialRect) { setCropRegions(prev => prev.map(r => r.id === activeCropId ? { ...r, x: Math.max(0, Math.min(100 - r.w, initialRect.x + (pos.x - startPos.x))), y: Math.max(0, Math.min(100 - r.h, initialRect.y + (pos.y - startPos.y))) } : r)); }
      else if (isResizing && activeCropId && initialRect) { 
          const dx = pos.x - startPos.x; const dy = pos.y - startPos.y;
          setCropRegions(prev => prev.map(r => {
              if (r.id !== activeCropId) return r;
              let { x, y, w, h } = initialRect;
              if (isResizing.includes('t')) { const newY = Math.max(0, y + dy); h = h + (y - newY); y = newY; }
              if (isResizing.includes('b')) { h = Math.max(1, Math.min(100 - y, h + dy)); }
              if (isResizing.includes('l')) { const newX = Math.max(0, x + dx); w = w + (x - newX); x = newX; }
              if (isResizing.includes('r')) { w = Math.max(1, Math.min(100 - x, w + dx)); }
              return { ...r, x, y, w, h };
          })); 
      }
  };
  const handleCropEnd = () => {
      if (isDrawing && currentRect && currentRect.w > 2 && currentRect.h > 2) { const newCrop = { ...currentRect, id: crypto.randomUUID() }; setCropRegions(prev => [...prev, newCrop]); setActiveCropId(newCrop.id); }
      setIsDrawing(false); setIsMoving(false); setIsResizing(null); setCurrentRect(null);
  };
  const processCrops = async () => {
      if (!cropperImage || !cropperImgRef.current) return;
      const sourceImg = new Image(); sourceImg.src = cropperImage;
      await new Promise(r => sourceImg.onload = r);
      const newTasks: ProcessingTask[] = [];
      for (let i = 0; i < cropRegions.length; i++) {
          const crop = cropRegions[i];
          const canvas = document.createElement('canvas');
          canvas.width = (crop.w/100)*sourceImg.naturalWidth; canvas.height = (crop.h/100)*sourceImg.naturalHeight;
          const ctx = canvas.getContext('2d');
          if (ctx) {
              ctx.drawImage(sourceImg, (crop.x/100)*sourceImg.naturalWidth, (crop.y/100)*sourceImg.naturalHeight, canvas.width, canvas.height, 0, 0, canvas.width, canvas.height);
              const blob = await new Promise<Blob | null>(res => canvas.toBlob(res, 'image/jpeg', 0.95));
              if (blob) {
                  const id = crypto.randomUUID(); filesMap.current.set(id, blob);
                  newTasks.push({ id, fileName: `CROP_${i+1}.jpg`, status: 'pending', progress: 0, batchIndex: 1, previewUrl: URL.createObjectURL(blob) });
              }
          }
      }
      setTasks(prev => [...prev, ...newTasks]); setPdfDoc(null); setCropperImage(null); setViewMode('file');
  };

  useEffect(() => { if (viewMode === 'file' && !isQueuePaused) processQueue(); }, [viewMode, isQueuePaused, processQueue]);

  // Updated filtering logic for visibleCards to include global search
  const visibleCards = useMemo(() => {
    // If there is a search query, ignore activeCategory and search ALL cards.
    if (searchQuery.trim()) {
        const query = searchQuery.toLowerCase().trim();
        return cards.filter(c => 
            (c.firstName + ' ' + c.lastName).toLowerCase().includes(query) ||
            (c.company || '').toLowerCase().includes(query) ||
            (c.title || '').toLowerCase().includes(query) ||
            (c.email || '').toLowerCase().includes(query)
        );
    }
    // If no search query, filter by active category.
    return cards.filter(c => c.category === activeCategory);
  }, [cards, activeCategory, searchQuery]);

  const activeTasks = useMemo(() => tasks.filter(t => t.status === 'pending' || t.status === 'processing' || t.status === 'error'), [tasks]);

  // --- Render ---
  return (
    <div className="flex h-screen w-full bg-slate-50 text-slate-900 font-sans overflow-hidden" onDragOver={onDragOver} onDragLeave={onDragLeave} onDrop={onDrop}>
      <input type="file" ref={fileInputRef} className="hidden" accept=".jpg, .jpeg, .png, .heic, .pdf, .xlsx" multiple onChange={(e) => processFiles(e.target.files)} />

      {/* Drag & Drop Overlay */}
      {isDragOver && (
          <div className="fixed inset-0 z-[1000] bg-indigo-600/90 backdrop-blur-sm flex items-center justify-center animate-fadeIn">
              <div className="text-white text-center">
                  <i className="fa-solid fa-cloud-arrow-up text-6xl mb-4 animate-bounce"></i>
                  <h2 className="text-3xl font-bold">釋放以匯入檔案或 Excel 備份</h2>
              </div>
          </div>
      )}

      {/* --- LEFT SIDEBAR (Navigation & List) --- */}
      <aside className={`${isMobile && viewMode !== 'file' ? 'hidden' : 'flex'} w-full md:w-[320px] lg:w-[380px] flex-row bg-white border-r border-slate-200 shadow-xl lg:shadow-none z-10 shrink-0`}>

         {/* 1. Left Task Rail (Queue & Quick Action) */}
         <div className="w-[64px] bg-slate-50 border-r border-slate-200 flex flex-col items-center py-4 gap-3 shrink-0 z-20">
             {/* Add Button */}
             <button onClick={() => fileInputRef.current?.click()} className="w-10 h-10 rounded-xl bg-indigo-600 text-white shadow-lg shadow-indigo-200 hover:bg-indigo-700 active:scale-95 transition-all flex items-center justify-center" title="上傳名片">
                 <i className="fa-solid fa-plus text-sm"></i>
             </button>

             {/* Divider */}
             <div className="w-6 h-px bg-slate-200 my-1"></div>

             {/* Task List - Vertical Scrollable Rail */}
             <div className="flex-1 w-full overflow-y-auto custom-scrollbar flex flex-col items-center gap-2 px-1 pb-4">
                 {activeTasks.map(task => (
                     <div key={task.id} className="relative w-10 h-10 rounded-lg bg-white border border-slate-200 shadow-sm shrink-0 overflow-hidden group cursor-help">
                         {task.previewUrl ? (
                             <img src={task.previewUrl} className="w-full h-full object-cover opacity-80" />
                         ) : (
